6: import { environment } from '../../../environments/environment';
7: 
8: /**
9:  * This class manage the http connections with internal REST services. Use the response format {
10:  *  Code: 'xxxxx',
11:  *  Body: 'Some Data' (this element is returned if the request is success)
12:  *  ...
13:  * }
14:  */
15: @Injectable({
16:   providedIn: 'root',
17: })
18: export class RequestManager {
19:   private path!: any;
20:   public httpOptions: any;
21:   constructor(private readonly http: HttpClient, private readonly errManager: HttpErrorManager) {
22:     const acces_token = localStorage.getItem('access_token');
23:     if (acces_token !== null) {
24:       this.httpOptions = {
25:         headers: new HttpHeaders({
26:           'Content-Type': 'application/json',
27:           Authorization: `Bearer ${acces_token}`,
28:         }),
29:       };
30:     }
31:   }
32: 
33:   /**
34:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
35:    * @param service: string
36:    */
37:   public setPath(service: string) {
38:     this.path = environment[service as keyof typeof environment];
39:   }
40: 
41:   /**
42:    * Perform a GET http request
43:    * @param endpoint service's end-point
44:    * @param params (an Key, Value object with que query params for the request)
45:    * @returns Observable<any>
46:    */
47:   get(endpoint: string) {
48:     return this.http.get<any>(`${this.path}${endpoint}`, this.httpOptions).pipe(
49:       catchError(this.errManager.handleError.bind(this))
50:     );
51:   }
52: 
53:   /**
54:    * Perform a POST http request
55:    * @param endpoint service's end-point
56:    * @param element data to send as JSON
57:    * @returns Observable<any>
58:    */
59:   post(endpoint: string, element: any) {
60:     return this.http
61:       .post<any>(`${this.path}${endpoint}`, element, this.httpOptions)
62:       .pipe(catchError(this.errManager.handleError));
63:   }
64: 
65:   /**
66:    * Perform a PUT http request
67:    * @param endpoint service's end-point
68:    * @param element data to send as JSON, With the id to UPDATE
69:    * @returns Observable<any>
70:    */
71:   put(endpoint: string, element: { Id: any }) {
72:     const path = element.Id
73:       ? `${this.path}${endpoint}/${element.Id}`
74:       : `${this.path}${endpoint}`;
75:     return this.http
76:       .put<any>(path, element, this.httpOptions)
77:       .pipe(catchError(this.errManager.handleError));
78:   }
79:   /**
80:    * Perform a DELETE http request
81:    * @param endpoint service's end-point
82:    * @param id element's id for remove
83:    * @returns Observable<any>
84:    */
85:   delete(endpoint: any, id: any) {
86:     return this.http
87:       .delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions)
88:       .pipe(catchError(this.errManager.handleError));
89:   }
90: }

